from sol_execbench.core.bench.timing import time_runnable
import b200probe
sys.path.insert(0,"/tmp")
TK = '''
import triton, triton.language as tl
@triton.jit
def tk_h(g,x,s,o,n,BLOCK: tl.constexpr):
    offs = tl.program_id(0)*BLOCK + tl.arange(0,BLOCK); m = offs<n
    a=tl.load(g+offs,m,eviction_policy="evict_first"); b=tl.load(x+offs,m,eviction_policy="evict_first"); c=tl.load(s+offs,m,eviction_policy="evict_first")
    tl.store(o+offs, a*(c*(1.0+b*(1.0-c))), m, eviction_policy="evict_last")
@triton.jit
def tk_p(g,x,s,o,n,BLOCK: tl.constexpr):
    offs = tl.program_id(0)*BLOCK + tl.arange(0,BLOCK); m = offs<n
    a=tl.load(g+offs,m); b=tl.load(x+offs,m); c=tl.load(s+offs,m)
    tl.store(o+offs, a*(c*(1.0+b*(1.0-c))), m)
'''
open("/tmp/tkm_tk5.py","w").write(TK)
import tkm_tk5 as M
CU = r'''
__device__ __forceinline__ float f(float g, float x, float s){return __fmul_rn(g,__fmul_rn(s,__fadd_rn(1.0f,__fmul_rn(x,__fsub_rn(1.0f,s)))));}
extern "C" __global__ void __launch_bounds__(256) k_h(const float* __restrict__ g,const float* __restrict__ x,const float* __restrict__ s,float* __restrict__ o,int n){
  int nvec=n>>2; int i=blockIdx.x*256+threadIdx.x;
  if(i<nvec){ float4 a,b,c; unsigned long long pl,ps;
      asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;":"=l"(pl));
      asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(ps));
      asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(a.x),"=f"(a.y),"=f"(a.z),"=f"(a.w):"l"(g+4*i),"l"(pl));
      asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(b.x),"=f"(b.y),"=f"(b.z),"=f"(b.w):"l"(x+4*i),"l"(pl));
      asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(c.x),"=f"(c.y),"=f"(c.z),"=f"(c.w):"l"(s+4*i),"l"(pl));
      float4 r; r.x=f(a.x,b.x,c.x); r.y=f(a.y,b.y,c.y); r.z=f(a.z,b.z,c.z); r.w=f(a.w,b.w,c.w);
      asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;"::"l"(o+4*i),"f"(r.x),"f"(r.y),"f"(r.z),"f"(r.w),"l"(ps):"memory");
  } else if(i==nvec){ for(int e=nvec<<2;e<n;++e) o[e]=f(g[e],x[e],s[e]); }
}'''
kh = b200probe.cuda_kernel(CU, "k_h")
def tr(fn,ins,outs):
    for _ in range(4):
        try: return [v*1e3 for v in time_runnable(fn,ins,outs,"cuda:0",warmup=10,rep=50,return_mode="all",methodology="cupti")]
        except ValueError as e: err=e
    return [float('nan')]
T0=time.time()
for n in [786432, 2097152, 8388608, 16777216]:
    ins=[torch.randn(n,device="cuda") for _ in range(3)]; out=torch.empty(n,device="cuda")
    gv=((n+3)//4+255)//256; gt=(n+1023)//1024
    K={"r0":lambda g,x,s,o: kh((gv,),(256,),g,x,s,o,n),
       "trh":lambda g,x,s,o: M.tk_h[(gt,)](g,x,s,o,n,BLOCK=1024,num_warps=4),
       "trh2k8":lambda g,x,s,o: M.tk_h[((n+2047)//2048,)](g,x,s,o,n,BLOCK=2048,num_warps=8),
       "trp_ind":lambda g,x,s,o: M.tk_p[(gt,)](g,x,s,o,n,BLOCK=1024,num_warps=4)}
    for k,fn in K.items(): fn(*ins,out)
    res={}
    for rep in range(4):
        for k,fn in (K.items() if rep%2==0 else reversed(list(K.items()))):
            t=tr(fn,ins,[out]); res.setdefault(k,[]).append((statistics.median(t),statistics.mean(t)))
    print(n, " ".join(f"{k}:{statistics.median([a for a,b in v]):.2f}/{statistics.median([b for a,b in v]):.2f}" for k,v in res.items()), f"[{time.time()-T0:.0f}s]", flush=True)

